// which must be Server, Docker-Distribution-Api-Version, WWW-Authenticate,
// Content-Type, Content-Length (the order of every NX-03 file), and writes
// WWW-Authenticate with its capitals, not as the canonical Www-Authenticate.
func TestEveryFixtureRoundTrips(t *testing.T) {
	files, err := filepath.Glob(filepath.Join("fixtures", "catalog", "*.http"))
	if err != nil {
		t.Fatal(err)
	}
	present := map[string]bool{}
	for _, path := range files {
		present[strings.TrimSuffix(filepath.Base(path), ".http")] = true
	}
	for _, name := range importedCatalog() {
		if !present[name] {
			t.Errorf("fixtures/catalog lacks the NX-03 file %s.http", name)
		}
	}
	for _, path := range files {
		name := strings.TrimSuffix(filepath.Base(path), ".http")
		t.Run(name, func(t *testing.T) {
			data, err := os.ReadFile(path)
			if err != nil {
				t.Fatal(err)
			}
			f, err := nexusfixture.Parse("catalog", filepath.Base(path), data)
			if err != nil {
				t.Fatalf("Parse: %v", err)
			}
			if got := nexusfixture.Format(f); !bytes.Equal(got, data) {
				t.Errorf("Format(Parse(b)) != b\n--- want\n%s\n--- got\n%s", data, got)
			}
		})
	}
}

// Import integrity: a verbatim body that Nexus sent with a Content-Length has
// through a proxy repository would cache an image and change the bench, so none
// is allowed, whatever the path says.
var (
	recordPaths = []*regexp.Regexp{
		regexp.MustCompile(`^/v2/(_catalog|[a-z0-9._/-]+/tags/list)?$`),
		regexp.MustCompile(`^/v2/[a-z0-9._-]+(/[a-z0-9._-]+)*/_catalog$`),
		regexp.MustCompile(`^/repository/[A-Za-z0-9._-]+/v2/_catalog$`),
		regexp.MustCompile(`^/service/rest/v1/repositories(/[A-Za-z0-9._-]+)*$`),
	}
	recordQueryParam = regexp.MustCompile(`^(n=[0-9]{1,6}|last=[A-Za-z0-9._/-]*)$`)
)

// refusedRequest returns why a request may not be sent, or "".
func refusedRequest(method, target string) string {
	p, query, hasQuery := strings.Cut(target, "?")
	switch {
	case method != http.MethodGet:
		return "the method is not GET"
	case strings.Contains(target, "..") || strings.Contains(target, "%"):
		return "the target holds a dot-dot or an escape"
	case strings.Contains(p+"/", "/manifests/") || strings.Contains(p+"/", "/blobs/"):
		return "a manifest or a blob read can change the bench"
	}
	listed := false
	for _, re := range recordPaths {
		listed = listed || re.MatchString(p)
	}
	if !listed {
		return "the path is not in the closed list"
	}
	if hasQuery {
		for _, param := range strings.Split(query, "&") {
